    50% { opacity: 0.4; }
}
@keyframes playPulse {
    0%, 100% { opacity: 1; transform: translate(-50%, -50%) scale(1); }
    50% { opacity: 0.75; transform: translate(-50%, -50%) scale(0.97); }
}
@keyframes ripple {
    0% { transform: scale(1); opacity: 0.6; }
    100% { transform: scale(2.2); opacity: 0; }
}
video { display: block; border: none; outline: none; box-sizing: border-box; }

